#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    // Each zero run of length z is crossed once by each of the a ones before it: a * (z + 1).
    long long ones = 0, cost = 0;
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '1') {
            ones++;
            i++;
            continue;
        }
        size_t end = i;
        while (end < s.size() && s[end] == '0') end++;
        cost += ones * (long long)(end - i + 1);
        i = end;
    }
    cout << cost << "\n";
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        // Each zero run of length z is crossed once by each of the a ones before it: a * (z + 1).
        long ones = 0, cost = 0;
        int i = 0, n = s.length();
        while (i < n) {
            if (s.charAt(i) == '1') {
                ones++;
                i++;
                continue;
            }
            int end = i;
            while (end < n && s.charAt(end) == '0') end++;
            cost += ones * (end - i + 1);
            i = end;
        }
        System.out.println(cost);
    }
}

